#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;
const int MAX_S = (1 << 20) + 5;

int n, fullMask, total;
int F1[MAX_S], F2[MAX_S];
int C[10][10], V[10][10], T[10][10][10];

long long modPow(long long b, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = (r * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1;
    }
    return r;
}

long long modInv(long long x) { return modPow(x, MOD - 2); }

bool ok(int a, int b, int c) {
    int vals[3] = {a, b, c};
    int idx[3] = {0, 1, 2};
    do {
        if (C[vals[idx[0]]][1] && C[vals[idx[1]]][2] && C[vals[idx[2]]][3]) return true;
    } while (next_permutation(idx, idx + 3));
    return false;
}

void walk1(int coef, int r, int c) {
    if (r == 7 && c == 1) {
        int state = 0;
        for (int i = 1; i <= 6; ++i)
            for (int j = i + 1; j <= 6; ++j)
                for (int k = j + 1; k <= 6; ++k)
                    if (ok(i, j, k)) {
                        int x = 1;
                        while (x == i || x == j || x == k) ++x;
                        int y = x + 1;
                        while (y == i || y == j || y == k) ++y;
                        int z = y + 1;
                        while (z == i || z == j || z == k) ++z;
                        state |= T[x][y][z];
                    }
        F1[state] = (F1[state] + coef) % MOD;
        return;
    }

    C[r][c] = 1;
    if (c == 3) walk1(1LL * coef * V[r][c] % MOD, r + 1, 1);
    else walk1(1LL * coef * V[r][c] % MOD, r, c + 1);
    C[r][c] = 0;

    if (c == 3) walk1(1LL * coef * (MOD + 1 - V[r][c]) % MOD, r + 1, 1);
    else walk1(1LL * coef * (MOD + 1 - V[r][c]) % MOD, r, c + 1);
}

void walk2(int coef, int r, int c) {
    if (r == 7 && c == 4) {
        int state = 0;
        for (int i = 1; i <= 6; ++i)
            for (int j = i + 1; j <= 6; ++j)
                for (int k = j + 1; k <= 6; ++k)
                    if (ok(i, j, k)) state |= T[i][j][k];
        F2[state] = (F2[state] + coef) % MOD;
        total = (total + 1LL * F1[fullMask ^ state] * coef) % MOD;
        return;
    }

    C[r][c - 3] = 1;
    if (c == 6) walk2(1LL * coef * V[r][c] % MOD, r + 1, 4);
    else walk2(1LL * coef * V[r][c] % MOD, r, c + 1);
    C[r][c - 3] = 0;

    if (c == 6) walk2(1LL * coef * (MOD + 1 - V[r][c]) % MOD, r + 1, 4);
    else walk2(1LL * coef * (MOD + 1 - V[r][c]) % MOD, r, c + 1);
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            int t; scanf("%d", &t);
            V[i][j] = 1LL * t * modInv(100) % MOD;
        }
    for (int i = n + 1; i <= 6; ++i) V[i][i] = 1;

    int bit = 0;
    for (int i = 1; i <= 6; ++i)
        for (int j = i + 1; j <= 6; ++j)
            for (int k = j + 1; k <= 6; ++k)
                T[i][j][k] = 1 << bit++;

    walk1(1, 1, 1);
    fullMask = (1 << 20) - 1;

    for (int b = 0; b < 20; ++b)
        for (int s = 0; s <= fullMask; ++s)
            if (s >> b & 1)
                F1[s] = (F1[s] + F1[s ^ (1 << b)]) % MOD;

    walk2(1, 1, 4);
    total = (MOD + 1 - total) % MOD;
    printf("%d\n", total);
    return 0;
}
